        company_business_key,
        company_status,
        company_fund_source_id,
        company_sub_sector,
        company_reported_on
    from {{ ref("investment__portfolio_company_vault__base") }}
    where company_business_key is not null
),
sat_portfolio_company_observed_fingerprinted as (
    select
        {{ dpf_vault_hash(["company_business_key"]) }} as portfolio_company_hk,
        {{ dpf_vault_hash(["company_status", "company_fund_source_id"]) }} as hashdiff,
        1 as hashdiff_basis_version,
        company_status,
        company_fund_source_id,
        company_sub_sector,
        company_reported_on as effective_from,
        {{ dpf_publish_timestamp() }} as load_datetime,
        'investment.portfolio_company_vault' as record_source
    from sat_portfolio_company_observed_source
),
sat_portfolio_company_observed_unstored as (
    select
        portfolio_company_hk,
        hashdiff,
        hashdiff_basis_version,
        company_status,
        company_fund_source_id,
        company_sub_sector,
        effective_from,
        load_datetime,
        record_source
    from sat_portfolio_company_observed_fingerprinted
    where {{ dpf_vault_new_versions("sat_portfolio_company_observed_fingerprinted", "portfolio_company_hk", "hashdiff", "effective_from", "hashdiff_basis_version", "history") }}
)

